-- Restaurant-only schema; Auth belongs to the dedicated Supabase project.
grant usage on schema public to anon,authenticated,service_role;
create schema if not exists restaurant_private;
revoke all on schema restaurant_private from public,anon,authenticated;
grant usage on schema restaurant_private to anon,authenticated,service_role;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '' check(length(display_name)<=100),phone text not null default '' check(length(phone)<=32),updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),slug text not null unique check(length(slug) between 1 and 100),name text not null check(length(name) between 1 and 100),active boolean not null default true,sort_order integer not null default 0,version integer not null default 1);
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories(id),slug text not null unique check(length(slug) between 1 and 150),name text not null check(length(name) between 1 and 150),description text not null default '' check(length(description)<=1000),image_url text not null check(length(image_url)<=500),price_centavos bigint not null check(price_centavos between 1 and 10000000),active boolean not null default true,version integer not null default 1);
create index products_category on public.products(category_id);
create table public.restaurant_settings(id boolean primary key default true check(id),origin_lat numeric not null check(origin_lat between -90 and 90),origin_lng numeric not null check(origin_lng between -180 and 180),label text not null check(length(label) between 2 and 150),per_km_centavos integer not null check(per_km_centavos between 0 and 100000),minimum_centavos integer not null check(minimum_centavos between 0 and 100000),max_distance_metres integer not null check(max_distance_metres between 1 and 100000),enabled boolean not null default true,version integer not null default 1);
insert into public.restaurant_settings(origin_lat,origin_lng,label,per_km_centavos,minimum_centavos,max_distance_metres) values(14.5995,120.9842,'Demo pickup point — Metro Manila',1500,5000,25000);
create table restaurant_private.staff_memberships(user_id uuid primary key references auth.users(id) on delete cascade,active boolean not null default true,updated_at timestamptz not null default now());
create table restaurant_private.rate_limits(user_id uuid not null references auth.users(id) on delete cascade,kind text not null,window_start timestamptz not null,requests integer not null,primary key(user_id,kind));
create table restaurant_private.quote_reservations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,destination_lat numeric not null,destination_lng numeric not null,settings_version integer not null,created_at timestamptz not null default now(),stored boolean not null default false);
create table restaurant_private.delivery_quotes(id uuid primary key default gen_random_uuid(),reservation_id uuid not null unique references restaurant_private.quote_reservations(id),owner_id uuid not null references auth.users(id),destination_lat numeric not null,destination_lng numeric not null,origin_lat numeric not null,origin_lng numeric not null,settings_version integer not null,distance_metres numeric not null check(distance_metres between 0 and 100000),fee_centavos bigint not null check(fee_centavos between 0 and 10000000),issued_at timestamptz not null default now(),expires_at timestamptz not null,consumed_order_id uuid);
create index delivery_quotes_owner on restaurant_private.delivery_quotes(owner_id,expires_at);
create table public.orders(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id),request_id uuid not null unique,reference text not null unique,fulfillment text not null check(fulfillment in ('pickup','delivery')),status text not null default 'pending' check(status in ('pending','accepted','preparing','ready','out_for_delivery','completed','delivered','rejected','cancelled')),payment_state text not null default 'unpaid' check(payment_state in ('unpaid','collected')),recipient_name text not null,recipient_phone text not null,address text,destination_lat numeric,destination_lng numeric,notes text not null default '',subtotal_centavos bigint not null check(subtotal_centavos between 0 and 3000000000),delivery_fee_centavos bigint not null default 0 check(delivery_fee_centavos>=0),total_centavos bigint not null check(total_centavos between 0 and 3000000000),distance_metres numeric,settings_version integer,version integer not null default 1,created_at timestamptz not null default now(),unique(owner_id,request_id));
create index orders_owner_page on public.orders(owner_id,created_at desc,id desc);
create index orders_staff_page on public.orders(created_at desc,id desc);
create index orders_status on public.orders(status,fulfillment,created_at desc);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id),name text not null,unit_price_centavos bigint not null check(unit_price_centavos between 1 and 10000000),quantity integer not null check(quantity between 1 and 99),unique(order_id,product_id));
create index order_items_order on public.order_items(order_id);
create table public.order_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,actor_id uuid not null references auth.users(id),action_id uuid not null unique,action text not null,status text not null,created_at timestamptz not null default now());
create index order_events_order on public.order_events(order_id,created_at,id);
create table public.contact_messages(id uuid primary key default gen_random_uuid(),request_id uuid not null unique,owner_id uuid not null references auth.users(id),name text not null,email text not null,phone text not null default '',message text not null,created_at timestamptz not null default now(),reviewed_at timestamptz,version integer not null default 1);
create index contact_messages_owner on public.contact_messages(owner_id);
create table restaurant_private.order_requests(request_id uuid primary key,owner_id uuid not null references auth.users(id),payload_hash text,order_id uuid references public.orders(id),abandoned boolean not null default false);
create table restaurant_private.action_receipts(action_id uuid primary key,actor_id uuid not null references auth.users(id),payload_hash text not null,result jsonb not null,created_at timestamptz not null default now());
alter table restaurant_private.delivery_quotes add constraint consumed_order_fk foreign key(consumed_order_id) references public.orders(id);

create function restaurant_private.fail(code text,message text) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('ok',false,'code',code,'message',message)$$;
create function restaurant_private.success(data jsonb) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('ok',true,'data',data)$$;
create function restaurant_private.verified_user(user_id uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from auth.users u where u.id=user_id and u.email_confirmed_at is not null)$$;
create function restaurant_private.is_staff() returns boolean language sql stable security definer set search_path='' as $$select restaurant_private.verified_user(auth.uid()) and exists(select 1 from restaurant_private.staff_memberships s where s.user_id=auth.uid() and s.active)$$;
create function restaurant_private.my_access() returns jsonb language sql stable security definer set search_path='' as $$select restaurant_private.success(jsonb_build_object('verified',restaurant_private.verified_user(auth.uid()),'staff',restaurant_private.is_staff()))$$;
create function public.get_my_access() returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.my_access()$$;
create function restaurant_private.create_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,display_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'display_name',''),100));return new;end$$;
create trigger restaurant_user_profile after insert on auth.users for each row execute function restaurant_private.create_profile();
insert into public.profiles(id,display_name) select id,left(coalesce(raw_user_meta_data->>'display_name',''),100) from auth.users on conflict(id) do nothing;

create function restaurant_private.take_rate(p_user_id uuid,p_kind text,p_limit_count integer,p_seconds integer) returns boolean language plpgsql security definer set search_path='' as $$declare amount integer;begin
 insert into restaurant_private.rate_limits as r(user_id,kind,window_start,requests) values(p_user_id,p_kind,clock_timestamp(),1)
 on conflict(user_id,kind) do update set window_start=case when r.window_start<=clock_timestamp()-make_interval(secs=>p_seconds) then clock_timestamp() else r.window_start end,requests=case when r.window_start<=clock_timestamp()-make_interval(secs=>p_seconds) then 1 else r.requests+1 end returning requests into amount;
 return amount<=p_limit_count;end$$;
create function restaurant_private.reserve_quote(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare owner uuid;lat numeric;lng numeric;s public.restaurant_settings;r restaurant_private.quote_reservations;begin
 owner:=(p_request->>'ownerId')::uuid;lat:=(p_request->'destination'->>'lat')::numeric;lng:=(p_request->'destination'->>'lng')::numeric;
 if not restaurant_private.verified_user(owner) then return restaurant_private.fail('VERIFICATION_REQUIRED','Verify your email before requesting delivery.');end if;
 if lat is null or lng is null or not(lat between -90 and 90) or not(lng between -180 and 180) then return restaurant_private.fail('INVALID_DESTINATION','Choose a valid delivery pin.');end if;
 if not restaurant_private.take_rate(owner,'quote',5,60) then return restaurant_private.fail('RATE_LIMITED','Wait a minute before another delivery estimate.');end if;
 select * into s from public.restaurant_settings where id;
 if not s.enabled then return restaurant_private.fail('DELIVERY_DISABLED','Delivery is unavailable. Choose pickup.');end if;
 insert into restaurant_private.quote_reservations(owner_id,destination_lat,destination_lng,settings_version) values(owner,lat,lng,s.version) returning * into r;
 return restaurant_private.success(jsonb_build_object('id',r.id,'origin',jsonb_build_object('lat',s.origin_lat,'lng',s.origin_lng),'destination',jsonb_build_object('lat',lat,'lng',lng),'settingsVersion',s.version,'maxDistanceMetres',s.max_distance_metres));
 exception when invalid_text_representation or numeric_value_out_of_range then return restaurant_private.fail('INVALID_DESTINATION','Choose a valid delivery pin.');end$$;
create function restaurant_private.store_quote(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare r restaurant_private.quote_reservations;s public.restaurant_settings;q restaurant_private.delivery_quotes;distance numeric;fee bigint;issued timestamptz;begin
 distance:=(p_request->>'distanceMetres')::numeric;
 select * into r from restaurant_private.quote_reservations where id=(p_request->>'reservationId')::uuid for update;
 if not found or r.stored or r.created_at<clock_timestamp()-interval '30 seconds' then return restaurant_private.fail('QUOTE_REQUEST_EXPIRED','Confirm your pin and request a new estimate.');end if;
 if not restaurant_private.verified_user(r.owner_id) then return restaurant_private.fail('VERIFICATION_REQUIRED','Verify your email.');end if;
 select * into s from public.restaurant_settings where id for share;
 if r.settings_version<>s.version or not s.enabled then return restaurant_private.fail('POLICY_CHANGED','Delivery settings changed. Request a new estimate.');end if;
 if distance is null or not(distance between 0 and s.max_distance_metres) then return restaurant_private.fail('OUTSIDE_COVERAGE','No valid route within delivery coverage. Choose pickup.');end if;
 fee:=greatest(ceil(s.minimum_centavos::numeric/100),ceil(distance*s.per_km_centavos/100000))*100;issued:=clock_timestamp();
 insert into restaurant_private.delivery_quotes(reservation_id,owner_id,destination_lat,destination_lng,origin_lat,origin_lng,settings_version,distance_metres,fee_centavos,issued_at,expires_at) values(r.id,r.owner_id,r.destination_lat,r.destination_lng,s.origin_lat,s.origin_lng,s.version,distance,fee,issued,issued+interval '5 minutes') returning * into q;
 update restaurant_private.quote_reservations set stored=true where id=r.id;
 return restaurant_private.success(jsonb_build_object('id',q.id,'destination',jsonb_build_object('lat',q.destination_lat,'lng',q.destination_lng),'distanceMetres',q.distance_metres,'feeCentavos',q.fee_centavos,'settingsVersion',q.settings_version,'issuedAt',q.issued_at,'expiresAt',q.expires_at));
 exception when invalid_text_representation or numeric_value_out_of_range then return restaurant_private.fail('INVALID_ROUTE','The route could not be validated.');end$$;
create function public.reserve_quote_request(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.reserve_quote(p_request)$$;
create function public.store_delivery_quote(p_request jsonb) returns jsonb language sql security invoker set search_path='' as $$select restaurant_private.store_quote(p_request)$$;

alter table public.profiles enable row level security;
alter table public.categories enable row level security;
alter table public.products enable row level security;
alter table public.restaurant_settings enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.order_events enable row level security;
alter table public.contact_messages enable row level security;
alter table restaurant_private.staff_memberships enable row level security;
alter table restaurant_private.rate_limits enable row level security;
alter table restaurant_private.quote_reservations enable row level security;
alter table restaurant_private.delivery_quotes enable row level security;
alter table restaurant_private.order_requests enable row level security;
alter table restaurant_private.action_receipts enable row level security;
create policy active_categories on public.categories for select to anon,authenticated using(active);
create policy active_products on public.products for select to anon,authenticated using(active and exists(select 1 from public.categories c where c.id=category_id and c.active));
create policy public_delivery_settings on public.restaurant_settings for select to anon,authenticated using(true);
create policy own_profile_select on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy own_profile_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy own_orders on public.orders for select to authenticated using(owner_id=(select auth.uid()));
create policy own_items on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.owner_id=(select auth.uid())));
create policy own_events on public.order_events for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.owner_id=(select auth.uid())));
create policy own_contacts on public.contact_messages for select to authenticated using(owner_id=(select auth.uid()));
revoke all on all tables in schema public from anon,authenticated;
revoke all on all tables in schema restaurant_private from public,anon,authenticated;
grant select on public.categories,public.products,public.restaurant_settings to anon,authenticated;
grant select on public.profiles,public.orders,public.order_items,public.order_events,public.contact_messages to authenticated;
grant update(display_name,phone) on public.profiles to authenticated;
revoke all on all functions in schema restaurant_private from public,anon,authenticated;
revoke all on function public.get_my_access(),public.reserve_quote_request(jsonb),public.store_delivery_quote(jsonb) from public,anon,authenticated;
grant execute on function restaurant_private.my_access(),public.get_my_access() to anon,authenticated;
grant execute on function restaurant_private.reserve_quote(jsonb),restaurant_private.store_quote(jsonb),public.reserve_quote_request(jsonb),public.store_delivery_quote(jsonb) to service_role;
